import {useId} from "react";
export function SearchInput({value,onChange}:{value:string;onChange:(value:string)=>void}){const id=useId();return <div><label htmlFor={id}>Szukaj</label><input id={id} type="search" value={value} placeholder="Tytuł, tag lub osoba…" onChange={event=>onChange(event.currentTarget.value)} onKeyDown={event=>{if(event.key==="Escape"&&!event.nativeEvent.isComposing){event.preventDefault();onChange("");}}}/>{value.length>0&&<button type="button" aria-label="Wyczyść wyszukiwanie" onClick={()=>onChange("")}>×</button>}</div>;}
