type Ticket={id:number;title:string;tags:readonly string[]};
export function TagsEditor({initialTickets,selectedId}:{initialTickets:readonly Ticket[];selectedId:number|null}){const [tickets,setTickets]=useState(initialTickets);const selected=tickets.find(ticket=>ticket.id===selectedId)??null;if(!selected)return <p>Wybierz ticket</p>;return <section><p>{selected.tags.join(", ")}</p><TagInput key={selected.id} onAdd={newTag=>setTickets(previous=>previous.map(ticket=>ticket.id===selected.id&&!ticket.tags.includes(newTag)?{...ticket,tags:[...ticket.tags,newTag]}:ticket))}/></section>;}

